              F (Z_to_bv 64 ralloc_meta_entry) fc None m (seg_rom usegs))
    (MS (rt1_regs sc ra sp gp tp t0 t1 t2 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x22b50) fc None m (seg_rom usegs)).
